async function copyShareLink(value){try{await navigator.clipboard.writeText(value);return true;}catch(_){}const focus=document.activeElement,buffer=document.createElement('textarea');buffer.value=value;buffer.readOnly=true;buffer.style.cssText='position:fixed;inset:0;width:1px;height:1px;opacity:0;pointer-events:none';document.body.append(buffer);buffer.focus({preventScroll:true});buffer.select();let copied=false;try{copied=document.execCommand('copy');}catch(_){}buffer.remove();if(focus?.isConnected)focus.focus({preventScroll:true});return copied;}
async function share(path,title){const shareURL=new URL(prefix(path),location.origin);['from','return','v','layout','share'].forEach(k=>shareURL.searchParams.delete(k));const target=shareURL.href,shareTitle=shareMetadata[shareURL.pathname.slice(ROOT.length-1)]?.title||title.replace(/\s*\|\s*معاينة$/,'');if(navigator.share){try{await navigator.share(reviewedGuide()?{text:target}:{title:shareTitle,url:target});return;}catch(error){if(error.name==='AbortError')return;}}toast(await copyShareLink(target)?'تم نسخ الرابط':'تعذر النسخ؛ يمكنك نسخ الرابط من شريط العنوان');}
