const newEntryId=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
function ownURL(value){try{const u=new URL(value,location.origin);return u.origin===location.origin&&u.pathname.startsWith(ROOT);}catch(_){return false;}}
function initEntry(){const old=history.state?.fdPreviewRoute;if(old?.id){activeEntryId=old.id;return;}const entry={id:newEntryId(),previous:null};history.replaceState({...history.state,fdPreviewRoute:entry},'',location.href);activeEntryId=entry.id;}
function saveView(id=activeEntryId){if(!id||!route||route.type==='destinations')return;const grid=$('.units-grid');navViews[id]={path:route.path,filter,photoIndex,openSpecs:[...document.querySelectorAll('.spec')].flatMap((e,i)=>e.open?[i]:[]),gridLeft:grid?.scrollLeft||0,directoryTop:$('#resort-service-directory')?.scrollTop||0,serviceGroup:$('#resort-service-directory')?.dataset.serviceGroup,y:scrollY,faq:$('.faq-guide')?{group:$('.faq-guide').dataset.faqGroup,query:$('#faq-search').value,open:$('.faq-guide .faq[open]')?.id}:undefined,savedAt:Date.now()};const keys=Object.keys(navViews);while(keys.length>80)delete navViews[keys.shift()];try{sessionStorage.setItem(NAV_KEY,JSON.stringify(navViews));}catch(_){} }
function restoreView(){const snap=navViews[activeEntryId];if(!snap||snap.path!==route.path)return;if(Array.isArray(snap.openSpecs))document.querySelectorAll('.spec').forEach((e,i)=>{e.open=snap.openSpecs.includes(i);});const grid=$('.units-grid');if(grid){grid.scrollLeft=Number(snap.gridLeft)||0;grid.dispatchEvent(new Event('scroll'));}const directory=$('#resort-service-directory');if(directory)directory.scrollTop=Number(snap.directoryTop)||0;window.scrollTo({top:Number(snap.y)||0,behavior:'instant'});}
function labelForURL(value){
 const u=new URL(value,location.origin),path=u.pathname.slice(ROOT.length-1);
 if(path==='/')return 'الوجهات';
 for(const v of Object.keys(labels))if(path===`/${v}/`)return labels[v];
 if(path==='/cabins/')return 'الأكواخ';if(path==='/stay/sections/')return 'القسمان';
 if(path==='/resort-map/')return 'الخريطة';if(path==='/chalet-map/')return 'استكشف الشاليه';
 if(path.endsWith('/compare/'))return 'المقارنة';if(path.endsWith('/contact/'))return 'الموقع والتواصل';if(path.endsWith('/faq/'))return 'الأسئلة الشائعة';
 if(path.endsWith('/order/'))return 'ملخص الطلب';if(path.endsWith('/checkout/'))return 'تفاصيل الطلب';
 if(path==='/services/')return 'خدمات المنتجع';if(path==='/chalet/services/')return 'خدمات الشاليه';if(path==='/stay/services/')return 'خدمات الاستراحة';
 if(path.includes('guest-services'))return 'خدمات إقامتك';
 const uinfo=catalog.units.find(u=>u.path===path);if(uinfo)return uinfo.name;
 const sinfo=catalog.services.find(s=>s.path===path||['games','water'].includes(s.id)&&servicePath(s,'chalet')===path);if(sinfo)return sinfo.name;
 if(path.includes('-tour/'))return 'استكشاف الكوخ';return 'الوجهات';
}

function contextualBack(fallback){
 const previous=history.state?.fdPreviewRoute?.previous;
 let target=new URL(prefix(fallback),location.origin).href;
 if(previous?.id&&ownURL(previous.url)){
  const path=new URL(previous.url).pathname.slice(ROOT.length-1),source=catalog.units.find(u=>u.path===path),v=route.venue;
  const unitParents=v==='resort'?['/cabins/','/resort-map/']:v==='stay'?['/stay/sections/','/stay/compare/']:['/chalet/'];
  const allowed=route.type==='unit'?unitParents.includes(path):route.type==='tour'?source?.venue===v||unitParents.includes(path):route.type==='faq'?path===`/${v}/contact/`||source?.venue===v:false;
  if(allowed)target=previous.url;
 }
 const sameParent=previous?.id&&ownURL(previous.url)&&new URL(previous.url).pathname===new URL(target).pathname;
 return {url:sameParent?previous.url:target,label:labelForURL(target),native:Boolean(sameParent)};
}

